from typing import Dict, List, Set, Tuple

Vertex = Tuple[int, int]
Edge = Tuple[Vertex, Vertex]

def build_Ktt(t: int) -> Tuple[List[Vertex], List[Edge]]:
    a: List[Vertex] = [(0, i) for i in range(t)]
    b: List[Vertex] = [(1, j) for j in range(t)]
    return a + b, [(u, v) for u in a for v in b]

def is_cover(edges: List[Edge], cover: Set[Vertex]) -> bool:
    return all(u in cover or v in cover for u, v in edges)

def lemma_A_holds(t: int) -> bool:
    """One side of K_{t,t} is a size-t cover; check |E| = t^2 <= t * n."""
    verts, edges = build_Ktt(t)
    n: int = len(verts)
    cover: Set[Vertex] = {(0, i) for i in range(t)}
    return is_cover(edges, cover) and len(edges) <= len(cover) * n

if __name__ == "__main__":
    for t in range(1, 12):
        assert lemma_A_holds(t), f"Lemma A failed for t={t}"
        verts, edges = build_Ktt(t)
        print(f"t={t}: n={len(verts)} |E|={len(edges)} <= k*n={t*len(verts)}")
    print("Lemma A (cover caps edges) verified on K_{t,t}.")

from typing import Dict, List, Set, Tuple

Vertex = Tuple[int, int]
Edge = Tuple[Vertex, Vertex]

def components(verts: List[Vertex], edges: List[Edge]) -> List[Set[Vertex]]:
    parent: Dict[Vertex, Vertex] = {v: v for v in verts}
    def find(x: Vertex) -> Vertex:
        while parent[x] != x:
            parent[x] = parent[parent[x]]; x = parent[x]
        return x
    for u, v in edges:
        parent[find(u)] = find(v)
    groups: Dict[Vertex, Set[Vertex]] = {}
    for v in verts:
        groups.setdefault(find(v), set()).add(v)
    return list(groups.values())

def block_subgraph(t: int, k: int) -> Tuple[List[Vertex], List[Edge]]:
    """Keep disjoint K_{k,k} blocks inside K_{t,t}; each has cover size k."""
    a = [(0, i) for i in range(t)]; b = [(1, j) for j in range(t)]
    kept: List[Edge] = []
    r = 0
    while (r + 1) * k <= t:
        ab = [(0, i) for i in range(r*k, (r+1)*k)]
        bb = [(1, j) for j in range(r*k, (r+1)*k)]
        kept += [(u, v) for u in ab for v in bb]
        r += 1
    return a + b, kept

def verify_deletion_bound(c: int, d: int) -> bool:
    t = 2 * (1 + 2 * c) * d; n = 2 * t; k = (1 + c) * d
    verts, kept = block_subgraph(t, k)
    full = t * t
    deletions = full - len(kept)
    return deletions >= c * d * n and len(components(verts, kept)) >= 1

if __name__ == "__main__":
    for c, d in [(1, 3), (2, 3), (1, 5), (2, 5)]:
        assert verify_deletion_bound(c, d)
        t = 2*(1+2*c)*d; n = 2*t
        print(f"c={c} d={d}: t={t} n={n} deletion bound c*d*n={c*d*n} satisfied")
    print("Main Theorem deletion bound verified on explicit block subgraphs.")

